struct Original:H8SEmulator{int rh()const{return lastread;}int wh()const{return lastwrite;}void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t time;uint32_t address;uint8_t value;bool write;};
struct Bus:H8SDevice{Original&c;std::array<Event,16>e{};unsigned n=0;explicit Bus(Original&x):c(x){}bool observed(uint32_t a){return (a>=0xc000&&a<0x1d000)||a==0xfffe73||(a>=0xffffb2&&a<=0xffffb4);}uint8_t read(uint32_t a)override{auto v=c.memory[a];if(observed(a))e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(observed(a))e[n++]={c.cycles,a,v,true};c.memory[a]=v;}};
static unsigned bus(uint32_t a,unsigned bytes,int prev){unsigned n=0;for(unsigned i=0;i<bytes;++i){auto x=(a+i)&0xffffff;if(x<0x400000||(x>=0xfffd10&&x<0xffffa0)){if((prev&1)||x!=uint32_t(prev|1))n+=x<0x400000?3:1;prev=int(x);}else{n+=x>=0xffffa0?1:3;prev=-1;}}return n;}
static uint32_t seed=0xabc57fa1;static uint32_t rnd(){seed^=seed<<13;seed^=seed>>17;return seed^=seed<<5;}
int main(int argc,char**argv){if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 2;auto cpu=std::make_unique<Original>();auto state=std::make_unique<kstation::ControllerDeviceState>();cpu->loadmem(rom.data(),unsigned(rom.size()),0);Bus device(*cpu);cpu->memmap(&device,0xc000,0x11000);cpu->memmap(&device,0xfffd00,0x300);using S=kstation::SerialTxService::Stage;uint64_t phases=0,events=0,shorts=0,mutations=0;for(unsigned n=0;n<5000;++n){auto put=[&](uint32_t a,uint8_t v){cpu->memory[a]=state->memory[a]=v;};uint16_t consumer=uint16_t(n%7==0?0xffff:rnd()&255),producer=n%3==0?consumer:uint16_t((consumer+1)&255);put(0xc494,uint8_t(consumer>>8));put(0xc495,uint8_t(consumer));put(0xc492,uint8_t(producer>>8));put(0xc493,uint8_t(producer));put(0xc496+consumer,uint8_t(rnd()));put(0xfffe73,n%3==1?uint8_t(1+n%255):0);put(0xffffb2,uint8_t(rnd()));put(0xffffb3,uint8_t(rnd()));put(0xffffb4,uint8_t(rnd()));cpu->pc=cpu->makepc(0xb50);cpu->setSP(0xfffe80+(n%2));cpu->ccr=0x80;cpu->pending_irqs=0;cpu->cycles=n%101?rnd():~uint64_t(0)-3;cpu->history(-1,n%2?0xfffe79:0xfffe78);cpu->write32(0x3000,int(cpu->getSP()));kstation::ControllerSerialTxTask task;for(unsigned phase=0;!task.complete();++phase){if(phase>50)return 3;auto st=task.stage();auto pc=uint32_t(cpu->getPC());unsigned len=(st==S::RetainPrimary||st==S::RetainRealtimeSource||st==S::RetainQueuedSource||st==S::RestoreEmpty||st==S::RestoreSource||st==S::RestorePrimary||st==S::MaskConsumer)?4:(st==S::ReadRealtime||st==S::ClearRealtime||st==S::ReadConsumer||st==S::ReadProducer||st==S::LocateData||st==S::PublishConsumer)?6:2;kstation::ControllerSerialTxTask::Credits c{8+bus(cpu->getSP()-4,4,cpu->wh()),8+bus(cpu->getSP(),4,int(pc+len-1)),5+bus(cpu->getSP(),4,int(pc+len-1)),bus(0xfffe73,1,cpu->wh())};if(n%7==0&&st==S::ReadStatus){put(0xffffb4,uint8_t(rnd()));++mutations;}if(n%11==0&&st==S::ReadData){put(0xc496+consumer,uint8_t(rnd()));++mutations;}auto cost=task.nextClocks(c);unsigned calls=0;auto noRead=[&](uint32_t,unsigned){++calls;return 0;};auto noWrite=[&](uint32_t,uint8_t,unsigned){++calls;};for(unsigned b=0;b<cost;++b){if(task.advanceBefore(b,c,noRead,noWrite)||calls||task.stage()!=st)return 4;++shorts;}device.n=0;const auto start=cpu->cycles;cpu->step();std::array<Event,8>native{};unsigned count=0;auto read=[&](uint32_t a,unsigned off){auto v=state->memory[a];native[count++]={start+off,a,v,false};return v;};auto write=[&](uint32_t a,uint8_t v,unsigned off){state->memory[a]=v;native[count++]={start+off,a,v,true};};if(task.advanceBefore(cost,c,read,write)!=cost||cpu->cycles-start!=cost||device.n!=count){std::fprintf(stderr,"phase mismatch n=%u pc=%x cost=%u actual=%llu io=%u/%u\n",n,pc,cost,(unsigned long long)(cpu->cycles-start),device.n,count);return 5;}for(unsigned i=0;i<count;++i){auto x=device.e[i],y=native[i];if(x.time!=y.time||x.address!=y.address||x.value!=y.value||x.write!=y.write){std::fprintf(stderr,"event mismatch n=%u pc=%x idx=%u time=%llu/%llu address=%x/%x\n",n,pc,i,(unsigned long long)x.time,(unsigned long long)y.time,x.address,y.address);return 6;}}events+=count;++phases;}for(uint32_t a:{0xc492u,0xc493u,0xc494u,0xc495u,0xfffe73u,0xffffb2u,0xffffb3u,0xffffb4u})if(cpu->memory[a]!=state->memory[a])return 7;}std::printf("PASS CPU-free SCI TX: 5000 calls, %llu stages, %llu ordered events, %llu short budgets, %llu live mutations\n",(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts,(unsigned long long)mutations);}
